// ── Context hash ────────────────────────────────────────────────────────

/** Deterministic JSON: object keys sorted recursively, so equal inputs hash equal. */
export function canonicalJson(value: unknown): string {
  return JSON.stringify(sortKeys(value));
}

function sortKeys(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(sortKeys);
  if (value && typeof value === 'object' && !(value instanceof Date)) {
    const out: Record<string, unknown> = {};
    for (const key of Object.keys(value as Record<string, unknown>).sort()) {
      const v = (value as Record<string, unknown>)[key];
      if (v !== undefined) out[key] = sortKeys(v);
    }
    return out;
  }
  if (value instanceof Date) return value.toISOString();
  return value;
}

/**
 * Unsigned 64-bit FNV-1a (two 32-bit lanes) over the canonical JSON of the
 * parts. Detects a cursor replayed against a different action, table, sort
 * or query input — it is NOT tamper protection; nothing a cursor carries is
 * trusted for authorization.
 */
export function pageContextHash(parts: unknown): string {
  const text = canonicalJson(parts);
  let h1 = 0x811c9dc5;
  let h2 = 0x01000193 ^ 0x5bd1e995;
  for (let i = 0; i < text.length; i++) {
    const c = text.charCodeAt(i);
    h1 ^= c;
    h1 = Math.imul(h1, 0x01000193) >>> 0;
    h2 ^= c;
    h2 = Math.imul(h2, 0x01000193) >>> 0;
    h2 = (h2 ^ (h2 >>> 13)) >>> 0;
  }
  return (h1 >>> 0).toString(16).padStart(8, '0') + (h2 >>> 0).toString(16).padStart(8, '0');
}

// ── Cursor codec ────────────────────────────────────────────────────────

/** Column kinds a sort key may have; mirrors the compile-time allowlist. */
export type PageKeyType = 'string' | 'number' | 'boolean' | 'date' | 'bigint';

export interface PageKeyShape {
  field: string;
  type: PageKeyType;
}

/** Wire form of one sort-key value. */
function encodeValue(field: string, v: unknown): string | number | boolean {
  if (v === null || v === undefined) {
    throw new Error(`[pagination] sort column "${field}" is null on a boundary row — sort keys must be non-null.`);
  }
  if (v instanceof Date) return v.toISOString();
  if (typeof v === 'bigint') return v.toString();
  if (typeof v === 'string' || typeof v === 'number' || typeof v === 'boolean') return v;
  throw new Error(`[pagination] sort column "${field}" holds an unsupported value type (${typeof v}).`);
}

/** Mint a version-2 cursor for the boundary row's sort-key values. */
export function encodePageCursor(context: string, values: Array<string | number | boolean>): string {
  return b64urlEncode(JSON.stringify({ v: PAGE_CURSOR_VERSION, c: context, k: values }));
}

function invalidCursor(reason: string, details?: Record<string, unknown>): PaginationError {
  return new PaginationError(
    'PAGINATION_INVALID_CURSOR',
    `Invalid pagination cursor: ${reason}`,
    400,
    details,
    'Pass back the `nextCursor` a previous page of this action returned, unmodified, or omit it to start from the first page.',
  );
}

/**
 * Decode and validate a cursor against the expected context and key shape.
 * Returns the typed boundary values (Dates revived for `date` columns).
 */
export function decodePageCursor(raw: string, expect: { context: string; keys: PageKeyShape[] }): unknown[] {
  if (typeof raw !== 'string' || raw.length === 0) throw invalidCursor('empty');
  if (raw.length > PAGE_CURSOR_MAX_LENGTH) throw invalidCursor('too long', { maxLength: PAGE_CURSOR_MAX_LENGTH });
  if (!/^[A-Za-z0-9_-]+$/.test(raw)) throw invalidCursor('malformed');
  let parsed: any;
  try {
    parsed = JSON.parse(b64urlDecode(raw));
  } catch {
    throw invalidCursor('malformed');
  }
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) throw invalidCursor('malformed');
  if (parsed.v !== PAGE_CURSOR_VERSION) {
    throw invalidCursor('unsupported version', { version: parsed.v ?? null, expected: PAGE_CURSOR_VERSION });
  }
  if (typeof parsed.c !== 'string' || !Array.isArray(parsed.k)) throw invalidCursor('malformed');
  if (parsed.c !== expect.context) {
    throw new PaginationError(
      'PAGINATION_CURSOR_MISMATCH',
      'This cursor was issued for a different query.',
      400,
      undefined,
      'A cursor is bound to the action, table, sort and input it was minted for. Request the first page of this query and continue from its `nextCursor`.',
    );
  }
  if (parsed.k.length !== expect.keys.length) {
    throw invalidCursor('wrong number of values', { expected: expect.keys.length, received: parsed.k.length });
  }
  const values: unknown[] = [];
  for (let i = 0; i < expect.keys.length; i++) {
    const key = expect.keys[i];
    const v = parsed.k[i];
    switch (key.type) {
      case 'string':
        if (typeof v !== 'string') throw invalidCursor(`value ${i} must be a string`, { field: key.field });
        values.push(v);
        break;
      case 'number':
        if (typeof v !== 'number' || !Number.isFinite(v)) throw invalidCursor(`value ${i} must be a number`, { field: key.field });
        values.push(v);
        break;
      case 'boolean':
        if (typeof v !== 'boolean') throw invalidCursor(`value ${i} must be a boolean`, { field: key.field });
        values.push(v);
        break;
      case 'bigint':
        if (typeof v !== 'string' && typeof v !== 'number') throw invalidCursor(`value ${i} must be an integer`, { field: key.field });
        if (!/^-?\d+$/.test(String(v))) throw invalidCursor(`value ${i} must be an integer`, { field: key.field });
        values.push(BigInt(v));
        break;
      case 'date': {
        if (typeof v !== 'string' && typeof v !== 'number') throw invalidCursor(`value ${i} must be a timestamp`, { field: key.field });
        const d = new Date(v);
        if (Number.isNaN(d.getTime())) throw invalidCursor(`value ${i} must be a timestamp`, { field: key.field });
        values.push(d);
        break;
      }
      default:
        throw invalidCursor(`value ${i} has an unsupported type`, { field: key.field });
    }
  }
  return values;
}

/** Drizzle column `dataType` → cursor value type; null when unsupported. */
export function pageKeyType(column: any): PageKeyType | null {
  const dt = column?.dataType;
  if (dt === 'string' || dt === 'number' || dt === 'boolean' || dt === 'date' || dt === 'bigint') return dt;
  return null;
}

// ── Page helper ─────────────────────────────────────────────────────────

/** Clamp a requested limit into [1, max], falling back to the default. */
export function resolvePageLimit(raw: unknown, limit: { default: number; max: number }): number {
  const n = typeof raw === 'number' ? raw : typeof raw === 'string' && raw.trim() !== '' ? Number(raw) : NaN;
  if (!Number.isFinite(n)) return limit.default;
  return Math.min(Math.max(Math.floor(n), 1), limit.max);
}

/** The query context: every input field except the pagination parameters (and declared cursor aliases). */
export function pageQueryContext(input: Record<string, unknown> | undefined, cursorAliases: readonly string[] = []): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(input ?? {})) {
    if ((PAGE_PARAM_FIELDS as readonly string[]).includes(k)) continue;
    if (cursorAliases.includes(k)) continue;
    out[k] = v;
  }
  return out;
}

/**
 * Build the per-request page helper the route injects as `page`.
 *
 * `input` is the validated action input; `query` the raw query string of a
 * GET request (read only for the pagination parameters an `input` schema
 * without `pageInput()` would strip). `db` is the action's scoped handle.
 */
export function createActionPage(
  spec: ActionPageSpec,
  args: { db: any; ctx: AppContext; input?: Record<string, unknown>; query?: Record<string, unknown> },
): ActionPage {
  const input = args.input ?? {};
  const raw = { ...(args.query ?? {}), ...input };
  const limit = resolvePageLimit(raw.limit, spec.limit);
  const requestedSort = raw.sort;
  if (requestedSort !== undefined && requestedSort !== null && requestedSort !== '') {
    if (typeof requestedSort !== 'string' || !Object.prototype.hasOwnProperty.call(spec.sorts, requestedSort)) {
      throw new PaginationError(
        'PAGINATION_INVALID_SORT',
        `Unknown sort "${String(requestedSort)}".`,
        400,
        { sorts: Object.keys(spec.sorts) },
        `Pass one of: ${Object.keys(spec.sorts).join(', ')}.`,
      );
    }
  }
  const sort = typeof requestedSort === 'string' && requestedSort !== '' ? requestedSort : spec.defaultSort;
  const cursorAliases = spec.cursorAliases ?? [];
  let cursorRaw: unknown = raw.starting_after ?? raw.cursor;
  // A declared alias is read only when the canonical names are absent, so a
  // client that sends both cannot make them disagree.
  if (cursorRaw === undefined || cursorRaw === null || cursorRaw === '') {
    for (const alias of cursorAliases) {
      const v = raw[alias];
      if (v !== undefined && v !== null && v !== '') { cursorRaw = v; break; }
    }
  }
  if (cursorRaw !== undefined && cursorRaw !== null && typeof cursorRaw !== 'string') throw invalidCursor('malformed');
  const cursor = typeof cursorRaw === 'string' && cursorRaw !== '' ? cursorRaw : null;
  const queryContext = pageQueryContext(input, cursorAliases);

  const keysFor = (sortName: string): PageSortKey[] => {
    const keys = spec.sorts[sortName];
    if (!keys) {
      throw new PaginationError('PAGINATION_INVALID_SORT', `Unknown sort "${sortName}".`, 400, { sorts: Object.keys(spec.sorts) });
    }
    return keys;
  };
  const assertVisible = (keys: PageSortKey[]): void => {
    for (const key of keys) {
      const roles = spec.maskedShowRoles[key.field];
      if (roles && !passesRoleCheck(roles, args.ctx)) {
        throw new PaginationError(
          'PAGINATION_SORT_NOT_VISIBLE',
          `Sort key "${key.field}" is masked for this caller.`,
          403,
          { field: key.field },
          'A keyset cursor carries the boundary row\'s sort values; choose a sort over columns this caller may see.',
        );
      }
    }
  };
  const contextFor = (sortName: string): string =>
    pageContextHash({ a: spec.action, t: spec.table, s: sortName, q: queryContext });
  const columnsOf = (table: any, keys: PageSortKey[]): Record<string, any> => {
    let name: string;
    try {
      name = getTableName(table);
    } catch {
      throw new Error(`[pagination] action "${spec.action}": page helpers need the Drizzle table "${spec.table}".`);
    }
    if (name !== spec.table) {
      throw new Error(`[pagination] action "${spec.action}" is declared over table "${spec.table}", not "${name}".`);
    }
    const columns = getTableColumns(table) as Record<string, any>;
    for (const key of keys) {
      if (!columns[key.field]) throw new Error(`[pagination] action "${spec.action}": table "${spec.table}" has no column "${key.field}".`);
      if (!pageKeyType(columns[key.field])) throw new Error(`[pagination] action "${spec.action}": column "${key.field}" cannot be a sort key.`);
    }
    return columns;
  };
  const boundaryValues = (columns: Record<string, any> | null, keys: PageSortKey[], sortName: string): unknown[] | null => {
    if (!cursor) return null;
    return decodePageCursor(cursor, {
      context: contextFor(sortName),
      keys: keys.map((k) => ({ field: k.field, type: columns ? pageKeyType(columns[k.field])! : 'string' })),
    });
  };
  const finishRows = <TRow extends Record<string, any>>(
    rows: TRow[],
    keys: PageSortKey[],
    sortName: string,
    read: (row: TRow, field: string) => unknown,
    strip?: (row: TRow) => TRow,
  ): PageResult<TRow> => {
    const hasMore = rows.length > limit;
    const slice = hasMore ? rows.slice(0, limit) : rows;
    const last = slice.length > 0 ? slice[slice.length - 1] : null;
    const nextCursor = hasMore && last
      ? encodePageCursor(contextFor(sortName), keys.map((k) => encodeValue(k.field, read(last, k.field))))
      : null;
    const data = strip ? slice.map(strip) : slice;
    return { data, pagination: { count: data.length, pageSize: limit, hasMore, nextCursor, sort: sortName } };
  };

  return {
    limit,
    sort,
    cursor,
    keyset(table: any, sortName: string = sort): SQL | undefined {
      const keys = keysFor(sortName);
      assertVisible(keys);
      const columns = columnsOf(table, keys);
      const values = boundaryValues(columns, keys, sortName);
      if (!values) return undefined;
      return keysetAfter(keys.map((k) => ({ column: columns[k.field], desc: k.desc })), values);
    },
    orderBy(table: any, sortName: string = sort): SQL[] {
      const keys = keysFor(sortName);
      const columns = columnsOf(table, keys);
      return keys.map((k) => (k.desc ? desc : asc)(columns[k.field]));
    },
    finish<TRow extends Record<string, any>>(rows: TRow[], sortName: string = sort): PageResult<TRow> {
      const keys = keysFor(sortName);
      assertVisible(keys);
      return finishRows(rows, keys, sortName, (row, field) => row[field]);
    },
    async query<TRow = Record<string, any>>(table: any, opts: PageQueryOptions = {}): Promise<PageResult<TRow>> {
      const sortName = opts.sort ?? sort;
      const keys = keysFor(sortName);
      assertVisible(keys);
      const columns = columnsOf(table, keys);
      const values = boundaryValues(columns, keys, sortName);
      const keyset = values ? keysetAfter(keys.map((k) => ({ column: columns[k.field], desc: k.desc })), values) : undefined;

      // A projection still needs every sort key for the cursor: fetch them
      // under reserved names and strip them before returning, so the
      // response carries exactly the selected fields.
      const hidden = new Map<string, string>();
      let selection: Record<string, unknown> | undefined;
      if (opts.select) {
        selection = { ...opts.select };
        for (const key of keys) {
          const alias = `__qb_page_${key.field}`;
          selection[alias] = columns[key.field];
          hidden.set(key.field, alias);
        }
      }

      let q: any = selection ? args.db.select(selection).from(table) : args.db.select().from(table);
      const conditions = [opts.where, keyset].filter((c) => c !== undefined && c !== null) as SQL[];
      if (conditions.length === 1) q = q.where(conditions[0]);
      else if (conditions.length > 1) q = q.where(and(...conditions));
      q = q.orderBy(...keys.map((k) => (k.desc ? desc : asc)(columns[k.field])));
      // Over-fetch one row: `rows.length === limit` would lie on a final page
      // that exactly fills the limit.
      q = q.limit(limit + 1);
      const rows = (await q) as Array<Record<string, any>>;

      return finishRows(
        rows as any[],
        keys,
        sortName,
        (row, field) => row[hidden.get(field) ?? field],
        hidden.size > 0
          ? (row) => {
              const out: Record<string, any> = { ...row };
              for (const alias of hidden.values()) delete out[alias];
              return out as any;
            }
          : undefined,
      ) as PageResult<TRow>;
    },
  };
}

